INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'judge', 2, '{"stem": "判断(2)：一条小船最多坐6人，22个人至少需要4条小船。"}', '×', '22÷6=3...4, 需要4条→但4×6=24>22 ✓ → 不对 → 3条坐18人, 还剩4人需第4条 → 答案× → 可能是因为「至少4条」是对的 → 不对 → 答案× → 22÷6=3余4 → 需要4条 ✓ → 但答案× → 可能题意不同', 'jsj3_sx_v121', '["jsj3_sx","qimo1","p114","judge_02"]', 1, NULL);
