INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 2, '{"stem": "应用(4)①：正方形玉米基地边长8m，靠墙围篱笆，至少需要多少米长的篱笆？"}', '24（米）', '靠墙→围3边: 8×3=24', 'jsj3_sx_v121', '["jsj3_sx","qimo1","p115","apply_04_1"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(4)②：围胡萝卜基地的篱笆和围玉米基地的篱笆同样长（24米），靠墙围，已知胡萝卜基地的长是12米，则宽是多少米？"}', '6（米）', '靠墙→围3边: 长+宽+长=24 → 不对 → (24-12)÷2=6 → 围法: 宽+长+宽=24 → (24-12)÷2=6', 'jsj3_sx_v121', '["jsj3_sx","qimo1","p115","apply_04_2"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(5)：手工小组要制作手机挂绳。每个挂绳需要4颗爱心形串珠和3颗五角星串珠。现有爱心形串珠139颗，五角星串珠80颗，这些串珠最多能制作多少个这样的手机挂绳？"}', '26（个）', '139÷4=34...3(爱心); 80÷3=26...2(五角星); 取较小值26', 'jsj3_sx_v121', '["jsj3_sx","qimo1","p115","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'apply', 3, '{"stem": "应用(6)：欢欢的爸爸明天要去美国出差，他出差7天的日期和正好是140，今天应该是几号？（7天出差天数包括出发和回家的天数）"}', '16号', '140÷7=20(中间日), 出发日=20-3=17号, 明天出发→今天=17-1=16号', 'jsj3_sx_v121', '["jsj3_sx","qimo1","p115","apply_06"]', 1, NULL);